import Link from "next/link";

export default function CommentSouscrire() {
  return (
    <main className="steps-page-shell">
      <div className="steps-page-container">
        <div className="steps-header">
          <Link href="/" className="back-link">
            ← Retour à l'accueil
          </Link>
          <h1 className="steps-main-title">
            <span className="title-dash">—</span> Comment souscrire ?
          </h1>
          <p className="steps-intro">
            Pour toute souscription auprès de IMPAXIS SECURITES à l'opération
            Emprunt Obligataire par Appel Public à L'Épargne, prévue du 22
            septembre au 10 octobre 2025.
            <br />
            Vous devez suivre les trois étapes ci-après :
          </p>
        </div>

        <div className="steps-list">
          {/* Étape 1 */}
          <div className="step-item">
            <div className="step-icon-wrapper">
              <div className="step-diamond">
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                  <polyline points="14 2 14 8 20 8" />
                  <line x1="16" y1="13" x2="8" y2="13" />
                  <line x1="16" y1="17" x2="8" y2="17" />
                  <polyline points="10 9 9 9 8 9" />
                </svg>
              </div>
              <span className="step-number">1</span>
            </div>
            <p className="step-text">
              <strong>Remplir le bulletin de souscription</strong> et nous le
              retourner
            </p>
          </div>

          {/* Étape 2 */}
          <div className="step-item">
            <div className="step-icon-wrapper">
              <div className="step-diamond">
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <path d="M3 22h18" />
                  <path d="M6 18v-7" />
                  <path d="M10 18v-7" />
                  <path d="M14 18v-7" />
                  <path d="M18 18v-7" />
                  <path d="M3 11l9-8 9 8" />
                </svg>
              </div>
              <span className="step-number">2</span>
            </div>
            <p className="step-text">
              <strong>Ouvrir un compte</strong> titres auprès de IMPAXIS
              SECURITES
            </p>
          </div>

          {/* Étape 3 */}
          <div className="step-item">
            <div className="step-icon-wrapper">
              <div className="step-diamond">
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <rect x="2" y="5" width="20" height="14" rx="2" />
                  <line x1="2" y1="10" x2="22" y2="10" />
                </svg>
              </div>
              <span className="step-number">3</span>
            </div>
            <p className="step-text">
              <strong>Alimenter votre compte</strong> après son ouverture :
              virement bancaire, remise en espèces au niveau des caisses de
              banques
            </p>
          </div>
        </div>
      </div>
    </main>
  );
}